module div_8bit (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output wire [15:0] result
);

    reg [15:0] remainder, quotient;
    reg [16:0] SR;
    reg [7:0] dividend_reg, divisor_reg;
    reg [4:0] cnt;
    reg [7:0] neg_divisor;
    reg start_cnt;
    reg [1:0] state, next_state;
    localparam IDLE = 2'b00;
    localparam DIVIDE = 2'b01;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
        end else begin
            state <= next_state;
            if (next_state == DIVIDE) begin
                res_valid <= (cnt == 8) & res_ready;
            end else begin
                res_valid <= 0;
            end
        end
    end

    always @(*) begin
        case (state)
            IDLE: begin
                if (opn_valid && !res_valid) begin
                    next_state = DIVIDE;
                end else begin
                    next_state = IDLE;
                end
            end
            DIVIDE: begin
                if (cnt == 8) begin
                    next_state = IDLE;
                end else begin
                    next_state = DIVIDE;
                end
            end
            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            dividend_reg <= 0;
            divisor_reg <= 0;
            remainder <= 0;
            quotient <= 0;
            SR <= 0;
        end else begin
            case (next_state)
                IDLE: begin
                    dividend_reg <= dividend;
                    divisor_reg <= divisor;
                    remainder <= 0;
                    quotient <= 0;
                    SR <= {dividend_reg[7], dividend_reg} << 1;
                end
                DIVIDE: begin
                    if (cnt[4]) begin
                        cnt <= 0;
                        start_cnt <= 0;
                        SR <= {remainder, quotient};
                    end else begin
                        cnt <= cnt + 1;
                        start_cnt <= 1;
                        remainder <= SR[15:8];
                        quotient <= SR[7:0];
                        SR <= {remainder, quotient};
                    end
                end
            endcase
        end
    end

    assign result = {remainder, quotient};

endmodule
